contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address accessControl) public {
        require(accessControl != address(0));
        bool reverted;
        c.initialize(accessControl); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted);
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encode(true);
    }

    receive() external payable {}
}

